import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { Heart } from 'lucide-react';
import { appwrite } from '../../services/supabaseClient';

export default function Login() {
  const navigate = useNavigate();
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const base = import.meta.env.BASE_URL || '/';
  const authBgImages = [
    `${base}hero-images/young-wedding-couple-enjoying-romantic-moments.jpg`,
  ];
  const [bgIndex, setBgIndex] = useState(0);
  useEffect(() => {
    authBgImages.forEach((s) => { const i = new Image(); i.src = s; });
    return () => {};
  }, []);
  useEffect(() => {
    authBgImages.forEach((s) => { const i = new Image(); i.src = s; });
    return () => {};
  }, []);

  const handleGoogleSignIn = async () => {
    setError('');
    setLoading(true);
    try {
      await appwrite.account.createOAuth2Session('google', `${window.location.origin}/onboarding`, `${window.location.origin}/dashboard`);
      // Appwrite will redirect to onboarding for new users, dashboard for returning users
      // Force reload to ensure AppContext updates
      window.location.reload();
    } catch (error) {
      let message = 'Google sign-in failed';
      if (error && typeof error === 'object' && 'message' in error) {
        message = (error as any).message;
      }
      setError(message);
      setLoading(false);
    }
  };

  // Show onboarding prompt for new Google users with no Vivaha info
  useEffect(() => {
    // Only run after Google sign-in
    const urlParams = new URLSearchParams(window.location.search);
    const fromGoogle = urlParams.get('provider') === 'google';
    if (!fromGoogle) return;
    const checkGoogleUser = async () => {
      try {
        const account = appwrite.account;
        const userData = await account.get();
        // Try to fetch onboarding document
        const databaseId = 'vivaha_db';
        const collectionId = 'onboarding';
        let onboardingDoc = null;
        try {
          onboardingDoc = await appwrite.databases.getDocument(databaseId, collectionId, userData.$id);
        } catch (err) {
          onboardingDoc = null;
        }
        if (onboardingDoc && onboardingDoc.role && onboardingDoc.weddingStyle) {
          // Save onboarding data to local context for dashboard
          localStorage.setItem('vivahaOnboarding', JSON.stringify(onboardingDoc));
          navigate('/dashboard');
        } else {
          navigate('/onboarding');
        }
      } catch (err) {
        navigate('/onboarding');
      }
    };
    checkGoogleUser();
  }, [navigate]);

  return (
    <div className="min-h-screen flex items-center justify-center px-4" style={{ backgroundImage: `url(${authBgImages[bgIndex]})`, backgroundSize: 'cover', backgroundPosition: 'center' }}>
      <div className="max-w-md w-full">
        <div className="text-center mb-8">
          <div className="text-left mb-4">
            <button onClick={() => navigate('/')} className="text-lg text-white font-medium hover:underline">← Back to Home</button>
          </div>
          <div className="flex justify-center mb-4">
            <div className="bg-primary-500 text-white p-4 rounded-full">
              <Heart className="w-12 h-12" />
            </div>
          </div>
          <h1 className="text-4xl font-bold text-white mb-2">Vivaha</h1>
          <p className="text-white font-medium">Plan your wedding like a pro</p>
        </div>

        <div className="bg-white rounded-2xl shadow-xl p-8">
          {error && (
            <div className="bg-red-50 text-red-600 p-3 rounded-lg text-sm mb-4">
              {error}
            </div>
          )}
          <button
            onClick={handleGoogleSignIn}
            disabled={loading}
            className="w-full bg-primary-500 hover:bg-primary-600 text-white font-medium py-3 rounded-lg transition disabled:opacity-50 flex items-center justify-center gap-2"
          >
            <img src="https://www.svgrepo.com/show/475656/google-color.svg" alt="Google" className="w-6 h-6" />
            {'Sign in with Google'}
          </button>
          <div className="mt-3 text-center text-xs text-gray-500 font-medium">
            Sign in is done through our authenticator
          </div>
          <p className="mt-6 text-center text-sm text-gray-600">
            Don't have an account?{' '}
            <button
              onClick={() => navigate('/register')}
              className="text-primary-500 hover:text-primary-600 font-medium"
            >
              Create one
            </button>
          </p>
        </div>
      </div>
    </div>
  );
}
