import { BrowserRouter as Router, Routes, Route, Navigate, useNavigate } from 'react-router-dom';
import { useState, useEffect } from 'react';
import Onboarding from './components/onboarding/Onboarding';
import Dashboard from './components/dashboard/Dashboard';
import WorkspaceLibrary from './components/workspace/WorkspaceLibrary';
import Login from './components/auth/Login';
import Register from './components/auth/Register';
import ForgotPassword from './components/auth/ForgotPassword';
import ResetPassword from './components/auth/ResetPassword';
import WelcomeBack from './components/WelcomeBack';
import Landing from './components/Landing';
import WhatIsVivaha from './components/WhatIsVivaha';
import DemoPage from './components/DemoPage';
import SharedDashboard from './components/dashboard/SharedDashboard';
import SharedWeddingInfo from './components/SharedWeddingInfo';
import AIAssistant from './components/AIAssistant';
import { useApp } from './context/AppContext';

function AppContent() {
  const navigate = useNavigate();
  // All state comes from useApp (context)

  // Listen for AI navigation commands
  useEffect(() => {
    const handleAINavigate = (event: Event) => {
      const customEvent = event as CustomEvent;
      if (customEvent.detail?.path) {
        navigate(customEvent.detail.path);
      }
    };

    window.addEventListener('aiNavigate', handleAINavigate);
    return () => window.removeEventListener('aiNavigate', handleAINavigate);
  }, [navigate]);

  const {
    isAuthenticated,
    hasCompletedOnboarding,
    isLoading,
    setOnboardingData,
    saveOnboarding
  } = useApp();

  if (isLoading) {
    return <div style={{ minHeight: '100vh', display: 'flex', alignItems: 'center', justifyContent: 'center' }}><span>Loading...</span></div>;
  }

  return (
    <Routes>
      {/* Always allow landing and public routes */}
      <Route path="/" element={<Landing />} />
      <Route path="/login" element={<Login />} />
      <Route path="/register" element={<Register />} />
      <Route path="/forgot-password" element={<ForgotPassword />} />
      <Route path="/reset-password" element={<ResetPassword />} />
      <Route path="/demo" element={<DemoPage />} />
      <Route path="/what-is-vivaha" element={<WhatIsVivaha />} />
      {/* Shared/Read-only dashboards */}
      <Route path="/shared/:shareId" element={<SharedDashboard />} />
      <Route path="/shared-wedding/:weddingId" element={<SharedWeddingInfo />} />
      {/* Onboarding for new users, only if user is valid */}
      {isAuthenticated && !hasCompletedOnboarding ? (
        <Route path="/onboarding/*" element={<Onboarding setHasCompletedOnboarding={() => window.location.href = '/dashboard'} />} />
      ) : null}
      {/* Authenticated routes, only if user and onboarding are valid */}
      {isAuthenticated && hasCompletedOnboarding ? (
        <>
          <Route path="/dashboard/*" element={<Dashboard />} />
          <Route path="/workspace/*" element={<WorkspaceLibrary />} />
          <Route path="/ai" element={<AIAssistant />} />
          <Route path="/welcome-back" element={<WelcomeBack />} />
        </>
      ) : null}
      {/* Fallback: if not authenticated, show landing page for all other routes */}
      {!isAuthenticated && (
        <Route path="*" element={<Landing />} />
      )}
    </Routes>
  );
}

export default AppContent;
